package org.sleepwell.app;

import org.junit.Test;
import static org.junit.Assert.*;

public class AlarmVolumeLeaseTest {
    static class Fake implements AlarmVolumeLease.Port,AlarmVolumeLease.Journal {int value=4,max=15,writes;boolean refuse;AlarmVolumeLease.State saved;public int read(){return value;}public int maximum(){return max;}public void write(int level){assertNotNull("Baseline must be journalled before raising volume",saved);value=level;writes++;}public AlarmVolumeLease.State load(){return saved;}public boolean save(AlarmVolumeLease.State value){if(refuse)return false;saved=value;return true;}public void clear(String owner){if(saved!=null&&saved.owner.equals(owner))saved=null;}AlarmVolumeLease lease(String run,String owner){return new AlarmVolumeLease(this,this,run,owner);}}
    private AlarmWakePolicy loud(){Alarm a=new Alarm(1);a.extraLoud=true;return new AlarmWakePolicy(a);}
    @Test public void baselineIsSavedBeforeWriteAndRestoredAfterStop(){Fake f=new Fake();AlarmVolumeLease l=f.lease("run","one");l.acquire(loud(),false);assertEquals(15,f.value);assertEquals(4,f.saved.original);l.release();assertEquals(4,f.value);assertNull(f.saved);}
    @Test public void externalUserVolumeSurvivesCleanup(){Fake f=new Fake();AlarmVolumeLease l=f.lease("run","one");l.acquire(loud(),false);f.value=7;l.release();assertEquals(7,f.value);assertNull(f.saved);}
    @Test public void sameRunRestartRetainsOriginalAndOldOwnerCannotRestore(){Fake f=new Fake();AlarmVolumeLease old=f.lease("run","one");old.acquire(loud(),false);AlarmVolumeLease fresh=f.lease("run","two");fresh.acquire(loud(),false);assertEquals(4,f.saved.original);old.release();assertEquals(15,f.value);fresh.release();assertEquals(4,f.value);}
    @Test public void restartDoesNotFightExternalChange(){Fake f=new Fake();f.lease("run","one").acquire(loud(),false);f.value=6;AlarmVolumeLease fresh=f.lease("run","two");fresh.acquire(loud(),false);assertEquals(6,f.value);assertTrue(f.saved.overridden);fresh.release();assertEquals(6,f.value);}
    @Test public void backupUsesLatestUserBaselineWhenUserChangedDuringPrimary(){Fake f=new Fake();AlarmVolumeLease l=f.lease("run","one");Alarm a=new Alarm(1);a.volume=40;l.acquire(new AlarmWakePolicy(a),false);f.value=8;l.acquire(loud(),true);assertEquals(15,f.value);l.release();assertEquals(8,f.value);}
    @Test public void newRunRecoversAnOrphanedOwnedBaseline(){Fake f=new Fake();f.lease("old","one").acquire(loud(),false);AlarmVolumeLease fresh=f.lease("new","two");fresh.acquire(loud(),false);assertEquals(4,f.saved.original);fresh.release();assertEquals(4,f.value);}
    @Test public void refusedJournalOrUnsupportedStreamNeverChangesVolume(){Fake f=new Fake();f.refuse=true;f.lease("run","one").acquire(loud(),false);assertEquals(0,f.writes);f.refuse=false;f.max=0;f.lease("run","two").acquire(loud(),false);assertEquals(0,f.writes);}
    @Test public void quietVolumeFailuresReturnConservativeDigitalGain(){Alarm a=new Alarm(-1);a.volume=100;AlarmWakePolicy quiet=new AlarmWakePolicy(a);Fake f=new Fake();f.value=15;f.refuse=true;assertEquals(.25,f.lease("run","one").acquire(quiet,false),0);f.refuse=false;f.max=0;assertEquals(.25,f.lease("run","two").acquire(quiet,true),0);Fake denied=new Fake(){@Override public void write(int value){throw new SecurityException();}};denied.value=15;assertEquals(.25,denied.lease("run","three").acquire(quiet,false),0);}
    @Test public void ignoredVolumeWriteIsCompensatedByDigitalGain(){Fake f=new Fake(){@Override public void write(int value){}};f.value=15;Alarm a=new Alarm(1);a.volume=40;assertEquals(.4,f.lease("run","one").acquire(new AlarmWakePolicy(a),false),.00001);}
    @Test public void quietUsesPermanentDigitalCapWithoutGlobalVolumeOrJournalChanges(){Fake f=new Fake();Alarm a=new Alarm(-1);a.volume=100;AlarmVolumeLease lease=f.lease("run","one");assertEquals(.25,lease.acquire(new AlarmWakePolicy(a),false),0);assertEquals(0,f.writes);assertNull(f.saved);f.value=15;assertEquals(.25,lease.acquire(new AlarmWakePolicy(a),true),0);lease.release();assertEquals(15,f.value);}
    @Test public void repeatedBackupModeTransitionsRestoreConfiguredLevelAndKeepOriginalBaseline(){Fake f=new Fake();Alarm a=new Alarm(1);a.volume=40;AlarmWakePolicy policy=new AlarmWakePolicy(a);AlarmVolumeLease lease=f.lease("run","owner");lease.acquire(policy,false);assertEquals(6,f.value);lease.acquire(policy,true);assertEquals(15,f.value);lease.acquire(policy,false);assertEquals(6,f.value);assertEquals(4,f.saved.original);int before=f.writes;lease.acquire(policy,false);assertEquals(before,f.writes);lease.acquire(policy,true);assertEquals(15,f.value);lease.acquire(policy,false);assertEquals(6,f.value);lease.release();assertEquals(4,f.value);}
    @Test public void primaryReturnPreservesUserChangedStreamWithBoundedDigitalCompensation(){Fake f=new Fake();Alarm a=new Alarm(1);a.volume=40;AlarmWakePolicy policy=new AlarmWakePolicy(a);AlarmVolumeLease lease=f.lease("run","owner");lease.acquire(policy,false);lease.acquire(policy,true);f.value=12;assertEquals(.5,lease.acquire(policy,false),0);assertEquals(12,f.value);assertTrue(f.saved.overridden);lease.release();assertEquals(12,f.value);}
    @Test public void ignoredDowngradeCannotLeavePrimaryDigitalOutputAtBackupGain(){Fake f=new Fake(){@Override public void write(int level){if(level==15)super.write(level);}};Alarm a=new Alarm(1);a.volume=40;AlarmWakePolicy policy=new AlarmWakePolicy(a);AlarmVolumeLease lease=f.lease("run","owner");lease.acquire(policy,true);assertEquals(15,f.value);assertEquals(.4,lease.acquire(policy,false),.00001);}
}
